/* ==UserStyle==
@name           StackOverflow - Atom One Dark - 2.0
@namespace      github.com/marslo
@preprocessor   stylus
@author         tekami ( v1 ) | marslo ( v2 )
@description    `A StackOverflow theme based on the popular Atom One Dark theme.`
@version        2.0.5
@license        CC-BY-4.0
@homepageURL    https://github.com/marslo/stylus-stackexchange-sites
@updateURL      https://github.com/marslo/stackexchange-sites/raw/main/stackexchange-sites.user.css
==/UserStyle== */

html {
    --bg: #333842;
    --bg2: #21252b;
    --bg3: #282c34;
    --text-color: #f0f0f0;
    --text-color-hl: #d1d1d1;
    --text-color-deep: #b3b3b3;
    --text-color-deep2: #525a6b;
    --text-color-invert: #1f1f1f;
    --hl_red: rgba(221,95,95,0.1);
    --hl_green: rgba(95,221,108,0.1);
    --a_yellow: #e5c07b;
    --a_blue: #61afef;
    --a_blue_deep: #157fd5;
    --a_accent1: #d38b50;
    --a_accent1_deep: #a96628;
    --a_accent1_hl: #edceb1;
    --a_accent2: #684ade;
    --a_accent2_deep: #443190;
    --a_accent2_hl: #7564b9;
    --so_orange: #f2740d;
/** crypto.stackexchange.com **/
    --theme-background-color: var(--bg3) !important;
  }
  header.s-topbar.ps-fixed {
    border-bottom: 1px solid var(--bg2);
  }
  body:not(.theme-dark) {
    color: var(--text-color);
