    [id="tinymce"],
    [class*="panel"],
    [class*="MW9GI"],
    [class*="InlineReview"]
  ) >
    h2:not(
      [class*="Overlay-"],
      [class*="css-"],
      [class*="fontBodyMedium"],
      [class*="panel-title"],
      [class*="spanh2"],
      [class*="style-name"],
      [class*="t-"],
      [data-v-0b7a2eac],
      [dir*="auto"],
      [id*="directions-mode-group"]
   ) >
