  /* ── fix sidebar + content layout ───────────────────────── */
  .vertical-tabs {
    display: flex !important;
  }
  .vertical-tabs__tabs {
    flex: 0 0 300px !important;
    max-width: 300px !important;
  }
  .vertical-tabs__panel {
    flex: 1 1 0 !important;
    min-width: 0 !important;
  }
  /* ── pypi doc (pip.pypa.io) ─────────────────────────────── */
  /* dark mode */
  @media (prefers-color-scheme: dark) {
    body:not([data-theme="light"]) .highlight .go {
      color: #878787 !important;
    }
  }
  /* light mode */
  .highlight .go {
    color: #686868 !important;
  }


  /* ── siliconflow (cloud.siliconflow.cn) ─────────────────── */
  .katex .mathnormal {
    font-family: 'FantasqueSansM Nerd Font' !important;
  }
  p[node="[object Object]"] + ol > li,
  p[node="[object Object]"] + ul > li {
    font-family: 'LXGWWenKaiMono Nerd Font Mono' !important;
  }


  /* ── others (onecompiler.com, etc.) ─────────────────────── */
  ::before, ::after, button, button.btn, span.fa-angle-up * {
    -webkit-box-sizing: border-box;
    -moz-box-sizing: border-box;
    box-sizing: border-box;
    font-family: inherit;
  }

  time, h2[class*="bottom"], .lwptoc_item,
  .MuiGrid-container h2 {                                     /* https://onecompiler.com/ */
    font-size: 14px !important;
  }
  .page-header a>b {                                          /* https://ci.jenkins.io/ */
    font-size: 20px !important;
  }
  ul.blockListLast > li.blockList,                            /* groovy doc */
  time-ago,
  td.colLast > div.block,                                     /* https://javadoc.jenkins.io */
  h4.line * {
    font-family: var(--font-family-sans) !important;
  }
  /* https://www.wikiwand.com/en/Web_colors */
  .mw-parser-output .color-chart-x11-table td:nth-child(2),
  .mw-parser-output .color-chart-x11-table td:nth-child(3),
  .entry pre>code {
    font-family: var(--font-family-mono) !important;
  }
  /* one.digicert.com */
  .Fields_hideShow__2EBZY {
    font-family: var(--font-family-mono) !important;
  }
  .wm_content__0bruk div {
    font-family: var(--font-family-sans) !important;
  }
  /* service now */
  ul[ng-if*="::user.logged_in"] span:where([class*="navbar-avatar"], [class*="visible-lg-inline"]),
  div[ng-show*="::!isViewNative"] div.logo-name {
    font-family: var(--font-family-handwritten) !important;
    font-size: 1.25em !important;
  }
  /* zoom.us */
  h1.r-title * {
    font-size: 22px !important;
  }
  /* csdn.net */
  .htmledit_views code ol {
    padding-bottom: 5px !important;
  }
  /* https://bingehacking.blogspot.com x span[style*="font-family"] */
  .PopularPosts, .post-title a {
    font-family: var(--font-family-sans) !important;
  }
  /* https://click.palletsprojects.com/en/8.1.x/api/ */
  span.pre {
    font-family: var(--font-family-mono) !important;
    font-size: var(--font-size-normal-mono) !important;
  }
  /* python api book */
  div[class*="highlight-"] pre {
    font-family: var(--font-family-mono) !important;
  }
  /* https://groovy-lang.org */
  i.conum {
    line-height: 20px !important;
  }

  /* google color picker */
  .KJEUee {
    line-height: 0.85 !important;
  }
  .B678Hb {
    font-size: 8px !important;
    font-family: var(--font-family-sans) !important;
  }
  .P2c8Dd {
    font-family: var(--font-family-mono) !important;
    font-size: var(--font-size-small-mono) !important;
  }

  /* docs.cloudbees.com */
  article.doc {
    max-width: 1288px !important;
  }

  /* groupid.marve11.com */
  .gid-input-text-field, #ssp-requests-filter .ssp-rf-form-control {
    padding: .65rem .65rem !important;
    border-radius: 1px;
    font-size: .75rem !important;
    height: 50px !important;
  }
  .ui-jqgrid .ui-jqgrid-htable th div {
    height: 30px !important;
  }

  /* https://crontab.guru */
  div.human-readable > i > span {
    font-family: var(--font-family-mono) !important;
  }

  /* flexera: https://flexera5new01.sample.com/codeinsight/FNCI#myprojectdetails/?id=702&tab=projectInventory&severity=HIGH&pinv=14884 */
  div.version-display-box {
    font-family: var(--font-family-mono) !important;
  }
  .x-body * {
    font-family: var(--font-family-sans) !important;
  }
  .x-panel-header-title-default * {
    font-size: var(--font-size-normal-sans) !important;
  }
  /* tips */
  div#ext-quicktips-tip-body * {
    font-family: var(--font-family-mono) !important;
    font-size: 10px !important;
  }
  div:has(> div > .version-display-box) {
    width: 45% !important;
  }
  .x-html-editor-tb .x-font-select {
    font-family: inherit !important;
  }

  div.ribbon-menu-text {
    font-size: 12px !important;
  }

  /* google meeting: https://meet.google.com */
  .iOzk7.JEC3ae .VbkSUe {                                                     /* captions */
    font-family: var(--font-family-sans) !important;
    font-size: 16px !important;
  }

  /* https://python.swaroopch.com/basics.html */
  .book .book-body div.page-wrapper div.page-inner {
    max-width: min(90vw, calc(100% - 200px)) !important;
  }


  /* ── icon settings ──────────────────────────────────────── */
  i[class*="fa-"],
  span[class*="glyphicon"],
  span[class*="style_Navbar"], span[class*="avatar"]:not([class*="gravatar-text"]), span[class*="icon-"],
  i[class*="material-icons-"],
  i[class*="google-material-icons"],
  i[class*="iconfont"],
  i[class*="ms-Button-icon"], [class*="ms-Button"], .icon-530,
  button[class*="vjs-"], .video-js,                           /* zoom.us */
  button[class*="zm-button"], i[class^=zm-icon-], i[class^=zm-dialog],
  [class*="g-button-right"] > [class*="icon-"],
  [class^="u-icon-"],
  .codicon[class*="codicon-"],                                /* gitpod */
  span[class^="icon"]::before,                                /* https://www4.benefitsolver.com/benefits/BenefitSolverView */
  div.content-post-body-content p,
  .docon {                                                    /* microsoft doc */
    font-family: var(--font-family-icon) !important;
  }
  /* google symbols: shape ligatures ( e.g. `chrome_extension` ) in 'Google Symbols' first */
  .google-symbols {
    font-family: 'Google Symbols', var(--font-family-icon) !important;
  }
  /* https://kubernetes.io/docs/tutorials/kubernetes-basics/create-cluster/cluster-interactive/  -> `form_`: service now incident */
  div#course-details i[class*="fa"],
  .fa, .section-directions, .fontHeadlineLarge, .file-name-idw,

   /* button--:  pypi */
  .button:not(a):not(
    [class*="aui-"],
    [value],
    [href="#"],
    [class*="button--"],
    [class*="feedback"],
    #banner-dismiss
  ):not(
    :is([class*="gravatar-form__content"] .button),
    :is([class*="table__align"] .button)
  ),
  .btn:not(
    a,
    .btn-default,
    [class*="mb-3"],
    [class*="form_"],
    [class*="-link"],
    [class*="text-"],
    [class*="-outline-"],
    [data-toggle="charmap"],
    [id*="_zoom_us"],
    [class*="animated"]
  ):not(
    :is(.d-flex > .btn),
    :is(.threat-hunting-homepage-button-group > .btn),
    :is(.btn-group > .btn),
    :is(.text-right > .btn),
    :is(.modal-body > .btn),
    :has(~ [class*="fossa"]),
    :is([class*="card"] .btn)
  ) {
    font-family: var(--font-family-icon) !important;
  }

  /* for zoom.us video control bar */
  .video-js .vjs-control-bar {
    font-family: var(--font-family-mono) !important;
  }

/**
   * groovy web console
  **/

  html { --font-size-big-mono: 22px; }

  .cm-editor *,
  div[class^="cm-"] *,
  [class*=cm-] {
    font-family: var(--font-family-mono) !important;
    font-size: var(--font-size-big-mono) !important;
    line-height: 1.5em !important;
  }

  [class*='cm-'] > span.ͼw {
    font-style: italic !important;
  }

  button {
    font-family: var(--font-family-icon) !important;
  }

/**
   * confluence pages
  **/

  html {
    color: #172b4d !important;
  }

  [class*="macro-param-desc"] code, [class*="macro-param-desc"] code * {
    line-height: unset !important;
  }

  div.codeContent *,
  pre, pre *,
  [class*="highlight"] :where(pre, code),
  body:not(.specificity-inc):not(.specificity-inc):not(.specificity-inc) .wiki-edit-content textarea.wiki-textfield {
    font-family: var(--font-family-mono) !important;
    font-size: var(--font-size-normal-mono) !important;
    line-height: 1.5em !important;
  }
  code, code * {
    font-family: var(--font-family-mono) !important;
    font-size: var(--font-size-small-mono) !important;
  }

  .wiki-content h1 {
    font-size: var(--font-size-h1) !important;
  }
  .wiki-content h2 {
    font-size: var(--font-size-h2) !important;
  }
  .wiki-content h3 {
    font-size: var(--font-size-h3) !important;
  }
  .wiki-content h4 {
    font-size: var(--font-size-h4) !important;
  }
  .space-information-container > div.name,
  .ia-secondary-header-title > span.label {
    font-family: var(--font-family-handwritten) !important;
  }
  .comments {
    font-style: italic !important;
    color: darkgray !important;
  }

/**
   * re dashboard pages
  **/

  html {
    --bs-font-sans-serif: "Titillium Nerd Font Upright", "Titillium Nerd Font", "Gisha Nerd Font", "Recursive Sans Casual Static Nerd Font", "Yoshe Shayufeite Nerd Font", "MicrosoftYaHei Nerd Font", "LXGWBright Nerd Font", "Qian Li Jiang Shan Nerd Font", "MFeltPenPRC Nerd Font", "MFeltPenHKSemi Nerd Font", "Grandstander Nerd Font", "Ubuntu", "Candara Nerd Font", "Titillium Up", Titillium, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Font Text";
    --bs-font-monospace: "OperatorMonoSSmLig Nerd Font Mono", "OperatorMonoLig Nerd Font Mono", "OperatorMono Nerd Font Mono", "BlexMonoLig Nerd Font Mono", "LektonLig Nerd Font Mono", "Lekton Nerd Font Mono", "JetBrainsMono Nerd Font Mono", "RecMonoCasual Nerd Font Mono", "Monaco Nerd Font Mono", Menlo, "Andale Mono", "Ubuntu Mono", "Monofur Nerd Font Mono", Consolas, "Yozai Nerd Font";
    --font-family-handwritten: "Papyrus Nerd Font", fantasy;
    --font-family-icon: "Google Material Icons", "Material Icons Extended", entypo, "Adgs Icons", "Google Symbols", "Font Awesome 7 Pro", "Font Awesome 5 Free", "Font Awesome 5 Pro", "Font Awesome 6 Free", "Font Awesome 6 Pro", FontAwesome, "Glyphicons Halflings", ReadMe-Icons, StructureFontAwesome, VideoJS, codicon, controlIcons, iconfont, iconfont-luckysheet, icozoom, retina_icons, streamline, union-design-icons, yunfont, okticon, docons, zipformplus, "Font Awesome 6 Brands", octicons, perforceIcons, FontADP, "Support MDL2 Assets", geico, marvell-icons, icomoon, element-icons, olive-icons, "SF Pro Icons", Iconochive-Regular, sans-serif;
  }

  /* :root cannot take value from var(..) */
  :root, [data-bs-theme=light], [data-bs-theme=dark] {
    --bs-font-sans-serif: "Titillium Nerd Font Upright", "Titillium Nerd Font", "Gisha Nerd Font", "Recursive Sans Casual Static Nerd Font", "Yoshe Shayufeite Nerd Font", "MicrosoftYaHei Nerd Font", "LXGWBright Nerd Font", "Qian Li Jiang Shan Nerd Font", "MFeltPenPRC Nerd Font", "MFeltPenHKSemi Nerd Font", "Grandstander Nerd Font", "Ubuntu", "Candara Nerd Font", "Titillium Up", Titillium, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Font Text" !important;
    --bs-font-monospace: "OperatorMonoSSmLig Nerd Font Mono", "OperatorMonoLig Nerd Font Mono", "OperatorMono Nerd Font Mono", "BlexMonoLig Nerd Font Mono", "LektonLig Nerd Font Mono", "Lekton Nerd Font Mono", "JetBrainsMono Nerd Font Mono", "RecMonoCasual Nerd Font Mono", "Monaco Nerd Font Mono", Menlo, "Andale Mono", "Ubuntu Mono", "Monofur Nerd Font Mono", Consolas, "Yozai Nerd Font" !important;
  }

  .g-0 {
    flex-wrap: nowrap !important;
  }
  .nav-link {
    white-space: nowrap !important;
  }

/**
   * jq online player
  **/

  :host, html {
    /* https://jqplay.org */
    --monaco-monospace-font: var(--font-family-mono) !important;
    font-family: var(--font-family-mono) !important;
    font-size: var(--font-size-big-mono) !important;
  }

  .monaco-editor, .monaco-editor *,
  .margin, .margin *,
  .line-numbers, .line-numbers *,
  .active-line-number, .active-line-number *,
  div.current-line, .current-line * {
    font-family: var(--font-family-mono) !important;
    --monaco-monospace-font:  var(--font-family-mono) !important;
    font-size: var(--font-size-big-mono) !important;
  }

/**
   * programming fonts
  **/

  .cm-comment { font-style: italic !important; }

/**
   * gerrit - gitblit
  **/

  @media (min-width: 1200px) {
    .container, .navbar-fixed-top .container, .navbar-fixed-bottom .container {
       width: 1170px;
    }
  }
  td#nums {
    width: 5% !important;
  }

/**
   * fossa
  **/

  [class*="fossa-list__row--center"],
  [class*="fossa-list__row--column"],
  [class*="fossa-list__row__title"],
  [class*="fossa-list__row__details__item"],
  [class*="fossa-list__row__details__item__trailing"] div,
  [class*="PD5ga73ugCA7Oc38"] div {
    font-family: var(--font-family-sans) !important;
  }

  div.margin-bottom-lg > p {
    font-family: Ellipsis,iA Writer Quattro,SF Mono,Menlo,Liberation Mono,DejaVu Sans Mono,Consolas,monospace !important;
  }

/**
   * git-scm.com/docs
  **/

  /* widen the outer docs wrapper to 85vw, keep horizontally centered */
  .inner,
  #content-wrapper {
    width: 85vw !important;
    max-width: 85vw !important;
    margin-left: auto !important;
    margin-right: auto !important;
  }

  /* keep the toc sidebar at its natural width; never let it shrink */
  #sidebar {
    flex: 0 0 auto !important;
  }

  /* content takes only the remaining space (flex-basis:0), min-width:0 lets it shrink so wide <pre> code blocks scroll internally instead of overflowing */
  #content {
    flex: 1 1 0 !important;
    width: auto !important;
    max-width: none !important;
    min-width: 0 !important;
  }

  code,
  #documentation #main dt.hdlist1,
  #documentation #main p em {
    font-family: var(--font-family-mono-accent) !important;
    font-size: var(--font-size-normal-mono) !important;
  }
  .edition2 code {
    color: #a3db72 !important;
  }

  pre,
  #documentation #main div.verseblock pre.content {
    font-family: var(--font-family-mono) !important;
    font-size: var(--font-size-big-mono) !important;
  }

/**
   * gemini
  **/

  /* ── BlexMonoLig Nerd Font Mono : book(350) → normal; text(450) → bold ── */
  /* normal(400) → Book(350) */
  @font-face { font-family:'Blex'; font-weight:normal; font-style:normal; src: local('BlexMonoLigNFM-Book'),       local('BlexMonoLig Nerd Font Mono Book');        }
  @font-face { font-family:'Blex'; font-weight:normal; font-style:italic; src: local('BlexMonoLigNFM-BookItalic'), local('BlexMonoLig Nerd Font Mono Book Italic'); }
  /* bold(700) → Text(450) */
  @font-face { font-family:'Blex'; font-weight:bold;   font-style:normal; src: local('BlexMonoLigNFM-Text'),       local('BlexMonoLig Nerd Font Mono Text');        }
  @font-face { font-family:'Blex'; font-weight:bold;   font-style:italic; src: local('BlexMonoLigNFM-TextItalic'), local('BlexMonoLig Nerd Font Mono Text Italic'); }

  :root {
      --font-family-mono-accent: "Blex", "Google Sans Code", ui-monospace, SFMono-Regular, 'SF Mono', Menlo, Consolas, 'Liberation Mono', monospace;
  }

  /* control the width of the outer container at the bottom and force it to be horizontally centered */
  .bottom-container,
  .input-area-container {
    max-width: 85vw !important;
    width: 100% !important;
    margin-left: auto !important;
    margin-right: auto !important;
  }

  /* fix the input box overflow issue (wrap the icon) */
  .text-input-field {
    max-width: 100% !important;
    width: 100% !important;
    box-sizing: border-box !important;
  }
  .trailing-actions-wrapper {
    flex-shrink: 0 !important;
  }

  /* chat history is forced to be horizontally centered */
  .conversation-container,
  infinite-scroller,
  chat-history {
    max-width: 85vw !important;
    width: 100% !important;
    margin-left: auto !important;
    margin-right: auto !important;
  }

  /* extend qa container and ai reply, fill the expanded parent container */
  user-query,
  user-query-content,
  .user-query-container,
  model-response,
  message-viewer,
  .message-content,
  .model-response-text,       /* AI reply text layer */
  generative-ui-response,     /* AI UI core components */
  dual-model-response {       /* dual-model contrast containers (occasionally) */
    max-width: 100% !important;
    width: 100% !important;
  }

  /* remove restrictions on hard-coding (708px) deeply nested markdown content */
  .markdown,
  .md-content,
  .markdown-main-panel,
  .markdown > *,
  .md-content > *,
  .markdown-main-panel > *,
  thinking-overlay,           /* thinking animation */
  .thinking-container {       /* thinking content */
    max-width: 100% !important;
  }

  /* prevent horizontal scrollbars */
  .code-block,
  pre {
    max-width: 100% !important;
  }

  /* action buttons row (thumb up/down, regenerate, share) — drop the 708px cap and auto-centering so the icons sit left under the reply */
  .response-container-footer,
  message-actions {
    max-width: 100% !important;
    width: 100% !important;
    margin-inline: 0 !important;
  }

  /* question bubble */
  .user-query-bubble-with-background {
    max-width: 60% !important;
  }


  /* override the hardcoded 692px max-width on the inner table container */
  div.table-block,
  .table-block.new-table-style {
    max-width: 100% !important;
    width: 100% !important;
  }

  /* ensure the actual table element expands to fill the new container width */
  .table-content,
  .table-content table {
    width: 100% !important;
    max-width: 100% !important;
  }

  /* code block fonts */
  .markdown pre:not(#_),
  .markdown pre code:not(#_),
  .code-block:not(#_),
  .code-block pre:not(#_),
  .code-block code:not(#_) {
    font-family: var(--font-family-mono-accent) !important;
  }

/**
   * claude.ai
  **/

  /* real width source: <main> */
  main {
    max-width: 85vw !important;
    width: 100% !important;
    margin-left: auto !important;
    margin-right: auto !important;
    padding-left: 0 !important;
    padding-right: 0 !important;
  }

  /* main width knob: message queue + input box -> max-w-3xl(~816px), extend to 85vw */
  div[class*="max-w-7xl"],
  div[class*="max-w-3xl"],
  div[class*="max-w-2xl"],
  div[class*="max-w-[50.5rem]"],
  [data-autoscroll-container="true"] > div {
    max-width: 85vw !important;
    width: 100% !important;
    margin-left: auto !important;
    margin-right: auto !important;
  }

  /* conversation view is driven by the --transcript-width var (default 48rem) — raise it so transcript + composer widen in QA mode */
  :root {
    --transcript-width: 85vw !important;
  }

  /* fallback: cap the transcript-width-governed containers directly in case the var is redefined closer */
  div[class*="transcript-width"] {
    max-width: 85vw !important;
  }

  /* user question bubble — 60% */
  [data-user-message-bubble="true"] {
    max-width: 60% !important;
  }

  /* code blocks / tables - do not display scroll bar in advance */
  pre,
  .code-block,
  table {
    max-width: 100% !important;
  }

/**
   * userstyles.world
   * edit / add / import / preview userstyle
  **/

  /* edit/add: form + alert width driven by --form-max-width; preview: main > * width driven by --layout-max-width — raise both to 85vw */
  main#content {
    --form-max-width: 85vw !important;
    --layout-max-width: 85vw !important;
  }

  /* fallback: cap the main sections directly in case the vars are redefined closer */
  main#content > * {
    max-width: 85vw !important;
  }

  /* source code + description + notes textareas */
  textarea#code[name="code"],
  textarea#description[name="description"],
  textarea#notes[name="notes"] {
    font-family: var(--font-family-mono) !important;
    font-size: var(--font-size-normal-mono) !important;
  }

