  src: url('https://github.com/marslo/fonts/raw/fonts/Operator/OperatorMonoSSmLigNF/otf/OperatorMonoSSmLigNerdFontMono-Light.otf') format('opentype');
}

@font-face {
  font-family: 'OperatorMonoSSmLig Nerd Font Mono';
  font-weight: 300;
  font-style: italic;
  src: url('https://github.com/marslo/fonts/raw/fonts/Operator/OperatorMonoSSmLigNF/otf/OperatorMonoSSmLigNerdFontMono-LightItalic.otf') format('opentype');
}

:root {
  --font-family-sans: /*[[font-family-sans]]*/;
  --font-family-mono: /*[[font-family-mono]]*/;
  --font-family-mono-accent: 'VictorMono Nerd Font Mono', 'Lekton Nerd Font Mono', 'LXGWWenKaiMono Nerd Font Mono', ui-monospace, SFMono-Regular, 'SF Mono', Menlo, Consolas, 'Liberation Mono', monospace;
  --font-family-handwritten: /*[[font-family-handwritten]]*/;
  --font-family-icon: /*[[font-family-icon]]*/;
  --font-family-override: /*[[font-family-sans]]*/;

  --font-size-big-sans: 20px;
  --font-size-normal-sans: 18px;
  --font-size-small-sans: 15px;

  --font-size-big-mono: 17px;
  --font-size-normal-mono: 15px;
  --font-size-small-mono: 14px;
  --font-size-xsmall-mono: 13px;

  --font-size-h1: 34px;
  --font-size-h2: 26px;
  --font-size-h3: 24px;
  --font-size-h4: 20px;
  --font-size-h5: 16px;
}


@-moz-document regexp("(?:https?://((?!([^/]*jenkins(?!gitpod)[^/]*\\.com/?.*|34\\.233.*|3\\.230.*|10\\.69.*|imarslo\\.jenkins\\.com|ci\\.jenkins\\.io).*|.*Monitor/$|.*sabacloud\\.com|.*detail.*pipeline|shields\\.io|127\\.0\\.0\\.1|0\\.0\\.0\\.0|localhost|.*fonts?.+\\.(com|org|net)|.*fonts?.(cn|netlify)|.*/fonts/.*|.*zijia.com.cn|.*sharepoint\\.com|programmingfonts|.*re-dashboard|jqplay\\.org|.*\\.github\\.dev|.*github\\.(com|io)|.*githubusercontent\\.(com|io)|.*\\.w3schools\\.com|artifactory.*\\.com/.*/groovydoc/|.*Iosevka|html-online).).*)|file://.*/git-doc/.+\\.html") {

  /**
