    --font-family-sans: /*[[font-family-sans]]*/;
    --font-family-mono: /*[[font-family-mono]]*/;

    /* cnn.com */
    --theme-font-family-ui: var(--font-family-sans) !important;
  }

  body {
    font-family: var(--font-family-sans), var(--font-family-mono) !important;

    /* vi.stackexchange.com */
    --ff-sans: var(--font-family-sans) !important;
    --ff-mono: var(--font-family-mono) !important;

    /* */
    --code-font-family: var(--font-family-mono) !important;
    --body-font-family: var(--font-family-sans) !important;

    /* pip doc */
    --font-stack--monospace: var(--font-family-mono) !important;
    --font-stack: var(--font-family-sans) !important;
  }

  /**
   * kbd, pre, code:                             html tag. e.g.: <kbd></kbd>, <pre></pre>
