    font-size: var(--font-size-normal-mono) !important;
  }


  /* ── others: github bits (readme-toc / BorderGrid / gogh github.io) ── */
  [data-target*="readme-toc.content"] *,
  .css-truncate a, .BorderGrid-cell,
  .terminal .bar .bar__title {                                /* https://gogh-co.github.io/Gogh */
    font-family: var(--font-family-sans) !important;
  }

  /* ── icon settings ──────────────────────────────────────── */
  i[class*="fa-"],
  span[class*="glyphicon"],
  span[class*="style_Navbar"], span[class*="avatar"]:not([class*="gravatar-text"]), span[class*="icon-"],
  i[class*="material-icons-"],
  i[class*="google-material-icons"],
  i[class*="iconfont"],
  i[class*="ms-Button-icon"], [class*="ms-Button"], .icon-530,
  [class*="g-button-right"] > [class*="icon-"],
  [class^="u-icon-"],
  .codicon[class*="codicon-"],                                /* gitpod */
  span[class^="icon"]::before,                                /* https://www4.benefitsolver.com/benefits/BenefitSolverView */
  div.content-post-body-content p,
  .google-symbols,
  .docon {                                                    /* microsoft doc */
    font-family: var(--font-family-icon) !important;
  }

  .fa, .section-directions, .fontHeadlineLarge, .file-name-idw,
  .button:not(a):not(
    [class*="aui-"],
    [value],
    [href="#"],
    [class*="feedback"],
    #banner-dismiss
  ):not(
    :is([class*="gravatar-form__content"] .button),
    :is([class*="table__align"] .button)
  ),
  .btn:not(
    a,
    .btn-default,
    [class*="mb-3"],
    [class*="form_"],
    [class*="-link"],
    [class*="text-"],
    [class*="-outline-"],
    [data-toggle="charmap"],
    [class*="animated"]
  ):not(
    :is(.d-flex > .btn),
    :is(.threat-hunting-homepage-button-group > .btn),
    :is(.btn-group > .btn),
    :is(.text-right > .btn),
    :is(.modal-body > .btn),
    :is([class*="card"] .btn)
  ) {
    font-family: var(--font-family-icon) !important;
  }

/**
   * github.com / github.io
  **/

  /* ── disable token warning ───────────────────────────────── */
  [class*="rgh-"] .flash.flash-error {
    display: none !important;
  }

  html {
    --font-size-github-mono: var(--font-size-normal-mono);
    --fontStack-monospace: var(--font-family-github-mono) !important;
    --fontStack-system: var(--font-family-sans) !important;
    --fontStack-sansSerif: var(--font-family-sans) !important;
    --body-font-size: var(--font-size-github-mono) !important;
    --font-size-small: var(--font-size-github-mono) !important;
  }

  body {
    /* github cursor position issue */
    --font-size-github-mono: var(--font-size-normal-mono);
    --fontStack-monospace: var(--font-family-github-mono) !important;
    --fontStack-system: var(--font-family-sans) !important;
    --fontStack-sansSerif: var(--font-family-sans) !important;
    --body-font-size: var(--font-size-github-mono) !important;
    --font-size-small: var(--font-size-github-mono) !important;
  }

  /* ── github.com overrides ───────────────────────────────── */
  /* ── PR review comment code: smaller font ───────────────── */
  /* conversation page (uses standard .blob-code classes) */
  .review-thread-component .blob-code-inner,
  .review-thread-component .blob-code-inner *,
  .review-thread-component .blob-code,
  .review-thread-component .blob-code *,
  .review-thread-component .blob-num,
  /* diff page: copilot suggestion cards */
  [class*="AutomatedReview"] [class*="DiffLines"],
  [class*="AutomatedReview"] [class*="DiffLines"] *,
  [class*="AutomatedReview"] .blob-code-inner,
  [class*="AutomatedReview"] .blob-code-inner *,
  [class*="AutomatedReview"] .blob-code,
  [class*="AutomatedReview"] .blob-code *,
  [class*="AutomatedReview"] .blob-num {
    font-size: var(--font-size-small-mono) !important;
  }

  pre > code, .markdown-body .highlight *,                                             /* github - code block */
  .blob-code, .blob-code-inner, .blob-code-inner *, [class*="blob"] code, .blob-num,   /* github - preview workflow file */
  .js-file-line * {                                                                    /* github - preview workflow file */
    font-size: var(--font-size-github-mono) !important;
  }

  .markdown-title,
  .markdown-section :is(p, h1, h2, h3, h4, h5, h6),
  .markdown-body, .markdown-body :is(p, h1, h2, h3, h4, h5, h6),
  div.list-style-none,
  .page-header,
  div[class*="style_CardRow"] h1,
  .d-flex.flex-self-stretch,
  a.dropdown-item,
  [class*="headline"],
  [class*="footer"],
  .d-flex.flex-wrap.flex-justify-end,
  label.header-search-wrapper > input,
  div.d-none.d-sm-block > span:is([class*="js-path-segment"]):not([class*="js-repo-root"]) > a,
  input:is([id*="password"], [id*="login"]) {
    font-family: var(--font-family-sans) !important;
  }
  /* ── for selection mismatches issue [class*="code"]:not([class*="react"]) ───────── */
  textarea#read-only-cursor-text-area,
  [class*='react-line'],
  [class*='react-code']:not([class*="-view"]),
  div[class*="styled-input-content"],                         /* github issue search */
  [class*="styled-input-container"] :is(input, span),         /* issues/PRs filter: input + width-measure span, same font as styled-input-content */
  div.QueryBuilder-StyledInputContainer,                      /* github search/query input box */
  .QueryBuilder-StyledInputContainer *,                       /* github search/query input box */
  .react-code-lines *,
  div.form-group textarea,
  [name^="ssh_key"],
  input:is([readonly="readonly"]),
  input.FormControl-input:is([aria-controls^="query-builder-"]),
  textarea#secret_value, input#secret_name,
   /* ── new issues filter input: fix cursor/font mismatch */
  [class*="Filter-module"] input,
  [class*="Input-module"] input[name="repository-input"],
  [class*="Input-module"] span {
    font-family: var(--font-family-github-mono) !important;
    font-size: var(--font-size-github-mono) !important;
  }

  /* ── new react diff view (PR/commit/compare): all languages ── */
  code[class*="diff-text"],                                  /* code cell + hunk header cell */
  code[class*="diff-text"] *,                                /* diff-text-inner, syntax/whitespace spans, +/- marker */
  td[class*="diff-line-number"] {                            /* line-number gutter */
    font-family: var(--font-family-github-mono) !important;
    font-size: var(--font-size-github-mono) !important;
  }


  /*  [class="TimelineItem-body"] code * */
  div[class*="code-scanning-"]:not(
    [class*="js-"],
    [class*="timeline"]
  ) {
    font-family: 'FantasqueSansM Nerd Font', 'RecMonoCasual Nerd Font Mono', 'VictorMono Nerd Font Mono', 'LXGWWenKaiMono Nerd Font Mono', ui-monospace, SFMono-Regular, 'SF Mono', Menlo, Consolas, 'Liberation Mono', monospace !important;
    font-size: var(--font-size-github-mono) !important;
  }

  /* issue comments */
  [class*="NewMarkdownViewer-module__safe-html-box"] {
    font-size: 17px !important;
  }

  /* github: go to file */
  .HVNDY { font-family: var(--font-family-sans) !important; }
  div[class*="Box-sc-"], div.ewmGxV { font-family: var(--font-family-github-mono) !important; }

  /* github revision number */
  a[href*="/commit/"][class*="prc-Button-ButtonBase"] [class*="prc-Button-Label"],
  .Link--secondary span {
    font-family: var(--font-family-github-mono) !important;
  }
  a:is([class*="-author"], [class*="user"]) {
    font-family: var(--font-family-handwritten) !important;
    font-size: var(--font-size-normal-sans);
  }
  .lh-condensed > a:not(
    [data-hydro-click],
    [data-hovercard-url],
    [class*="color-fg-"],
    [class*="Link--"]
  ) {
    font-family: 'VictorMono Nerd Font Mono', 'LXGWWenKaiMono Nerd Font Mono',  ui-monospace, SFMono-Regular, 'SF Mono', Menlo, Consolas, 'Liberation Mono', monospace !important;
    font-weight: bold;
  }
  .d-flex.flex-wrap.flex-justify-end [rel*="author"],
  header.pagehead h1,
  span.js-repo-root,
  div.vcard-names-container h1 .vcard-fullname,
  [data-hovercard-type="user"]  span.AppHeader-context-item-label,
  span:is([class^="AppHeader-context-item-label"]) {
    font-family: var(--font-family-handwritten) !important;
    font-size: 24px !important;
  }
  h3.text-normal a.author {
    padding-top: 0px !important;
  }
  h2.breadcrumb, .separator {
    font-size: 16px !important;
  }
  .markdown-body.js-comment-body p,
  h3.text-normal a.author,
  .d-none.d-sm-block,
  h2:is([id*="blob-path"]) {
    font-size: 18px !important;
  }
  .d-flex.flex-wrap.flex-justify-end [rel*="author"] {
    font-size: 24px !important;
  }
   /* payment method */
  .FormControl-input, .FormControl-select, .FormControl-textarea {
    font-size: var(--text-body-size-medium, 0.875rem) !important;
    line-height: var(--text-body-lineHeight-medium, 1.4285) !important;
  }
  select.select-input {
    font-size: 14px !important;
    line-height: 20px !important;
  }
  .book.font-size-2 .book-body .page-inner section {          /* https://psyteachr.github.io */
    font-size: 14px !important;
  }

  /* < Prev 1 2 3 4 5 Next > pagination */
  a[rel="prev"], a[rel="next"],
  a[rel="prev"]::before, a[rel="next"]::after {
    font-size: var(--font-size-small-sans) !important;
    font-family: var(--font-family-handwritten) !important;
  }
  a[rel="prev"]::before, a[rel="next"]::after {
    padding-top: 20px !important;
  }
  .gaSbTj {
    font-size: var(--font-size-small-sans) !important;
    font-family: var(--font-family-sans) !important;
  }

  /* ── search icon padding ─────────── */
  /**
   *  - .AppHeader .AppHeader-globalBar .AppHeader-search .AppHeader-search-kbd
   *  - .form-select                   : github drop-down list
  **/
  div.eIjUrw, div.qQkTK,                                      /* github search repositories */
  .line-number, .gr-diff,                                     /* github codeblock */
  .line:not([id*="table"]),                                   /* github codeblock && https://codeberg.org/vhs/jekyll-money */
  input:is([id="repos-list-filter-input"]) {
    font-family: var(--font-family-github-mono) !important;
    font-size: var(--font-size-big-mono) !important;
    line-height: 1.5em !important;
  }
  .AppHeader-search-kbd {
    align-content: center !important;
    height: var(--font-size-big-mono) !important;
    font-size: var(--font-size-big-mono) !important;
  }
  .AppHeader-searchButton {                                   /* type `/` to search */
    padding-left: 2em !important;
  }

  /* ── others ─────────── */
  span.cm-comment,                                            /* gist edit comment code */
  span.pl-c {                                                 /* github comment code */
    font-style: italic !important;
  }

  /* ── gist.github.com ─────────── */
  .select-sm {                                                /* gist select drop-down list */
    font-size: 12px !important;
  }
  a.wb-break-all strong {                                     /* gist.github.com */
    font-family: var(--font-family-sans) !important;
  }
  h1.wb-break-word.f3 > span.author > a,                      /* ╮                 */
  h3.text-normal a.author {                                   /* ╯ gist.github.com */
    font-family: var(--font-family-handwritten) !important;
    font-size: 24px !important;
  }
  h1:is([class*="text-normal"]):not([id*="summary-val"]) {    /* gist.github.com */
    font-size: var(--font-size-h2) !important;
    font-weight: 400 !important;
  }

  /* ── hidden GitHub：hidden「xxx had recent pushes」 ─────────── */
  /* check details in : https://github.com//${OWNRE}/${REPO}/show_partial?partial=tree%2Frecently_touched_branches_list */
  div[class*="RecentlyTouchedBranches-module"][class*="Flash"][data-variant="warning"],  /* css-module class: `…-module__Flash` → `…-module_<hash>_Flash` */
  div[data-url*="recently_touched_branches_list"] {
    display: none;
  }

  /* ── github.io (github pager / gitbook) ─────────────────── */
  .markdown-section code {
    font-family: var(--font-family-github-mono) !important;
    font-size: var(--font-size-small-mono) !important;
  }
  .markdown-section *:not(mark, span, h1, h2, h3, h4, a>code, code) {
    font-size: 16px !important;
  }
  .markdown-section a,
  .book-summary a,
  div[type*="text"],
  li li,
  ul li,
  ol li,
  #book-search-input>input,
  textarea[id*="commento-textarea"],
  a.btn,
  div.tags>b,
  input[type=checkbox]+label,
  .commento-submit-button,
  div[class*="language-liquid"]~table *,
  .book.font-family-1 {
    font-family: var(--font-family-sans) !important;
  }

  /* gitbook */
  span.token.comment {                                        /* comment code */
    font-style: italic !important;
    color: #b9b9b9 !important;
  }
  span.token.punctuation { color: #93a1a1 !important; }
  .page-inner { max-width: min(90vw, calc(100% - 200px)) !important; }   /* reserve nav-arrow gutter; see page-inner rule above */

  .code-wrapper pre > code > span.code-line:before {          /* line number */
    font-family: var(--font-family-github-mono) !important;
  }
  /*
  .token.entity { background: #2d3143; }
  .panel-default>.panel-heading { color: #eee8d5; }           * gitbook dark mode *
  */

