/* ==UserStyle==
@name           iFonts GitHub (marslo)
@version        1.0.6
@namespace      github.com/marslo
@description    github-only font customization
@author         marslo
@homepageURL    https://github.com/marslo/ifonts-github
@advanced       text font-family-sans        "Sans Fonts"        ""Titillium Nerd Font Upright", "Titillium Nerd Font", "Gisha Nerd Font", "Recursive Sans Casual Static Nerd Font", "Yoshe Shayufeite Nerd Font", "MicrosoftYaHei Nerd Font", "LXGWBright Nerd Font", "Qian Li Jiang Shan Nerd Font", "MFeltPenPRC Nerd Font", "MFeltPenHKSemi Nerd Font", "Grandstander Nerd Font", "Ubuntu", "Candara Nerd Font", "Titillium Up", Titillium, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Font Text""
@advanced       text font-family-github-mono "Mono Fonts"        ""Blex", "BlexMonoLig Nerd Font Mono", "OperatorMonoSSmLig Nerd Font Mono", "OperatorMonoLig Nerd Font Mono", "OperatorMono Nerd Font Mono", "Lekton Nerd Font Mono", "JetBrainsMono Nerd Font Mono", "RecMonoCasual Nerd Font Mono", "Monaco Nerd Font Mono", Menlo, "Andale Mono", "Ubuntu Mono", "Monofur Nerd Font Mono", Consolas, "Yozai Nerd Font""
@advanced       text font-family-handwritten "Handwritten Fonts" ""Papyrus Nerd Font", fantasy"
@advanced       text font-family-icon        "Icon Fonts"        ""Google Material Icons", "Material Icons Extended", entypo, "Adgs Icons", "Google Symbols", "Font Awesome 7 Pro", "Font Awesome 5 Free", "Font Awesome 5 Pro", "Font Awesome 6 Free", "Font Awesome 6 Pro", FontAwesome, "Glyphicons Halflings", ReadMe-Icons, StructureFontAwesome, VideoJS, codicon, controlIcons, iconfont, iconfont-luckysheet, icozoom, retina_icons, streamline, union-design-icons, yunfont, okticon, docons, zipformplus, "Font Awesome 6 Brands", octicons, perforceIcons, FontADP, "Support MDL2 Assets", geico, marvell-icons, icomoon, element-icons, olive-icons, "SF Pro Icons", Iconochive-Regular, sans-serif"
==/UserStyle== */

/* ╔════════════════════════════════════════════════════════════╗ */
/* ║              github: general rules (github.com/io)         ║ */
/* ╚════════════════════════════════════════════════════════════╝ */

@-moz-document regexp("https?://[^/]*github\\.(com|io).*"), regexp("https?://[^/]*githubusercontent\\.(com|io).*") {

  /**
   * github: general rules
  **/

  /* ── shared definitions (scoped to this domain; no global section) ── */
  @font-face { font-family: "San Francisco"; font-weight: 400; src: url("https://applesocial.s3.amazonaws.com/assets/styles/fonts/sanfrancisco/sanfranciscodisplay-regular-webfont.woff"); }
  @font-face { font-family: 'OperatorMonoSSmLig Nerd Font Mono'; font-weight: 300; font-style: normal; src: url('https://github.com/marslo/fonts/raw/fonts/Operator/OperatorMonoSSmLigNF/otf/OperatorMonoSSmLigNerdFontMono-Light.otf') format('opentype');       }
  @font-face { font-family: 'OperatorMonoSSmLig Nerd Font Mono'; font-weight: 300; font-style: italic; src: url('https://github.com/marslo/fonts/raw/fonts/Operator/OperatorMonoSSmLigNF/otf/OperatorMonoSSmLigNerdFontMono-LightItalic.otf') format('opentype'); }

  /* ── BlexMonoLig Nerd Font Mono : book(350) → normal; text(450) → bold ── */
  /* normal(400) → Book(350) */
  @font-face { font-family:'Blex'; font-weight:normal; font-style:normal; src: local('BlexMonoLigNFM-Book'),       local('BlexMonoLig Nerd Font Mono Book');        }
  @font-face { font-family:'Blex'; font-weight:normal; font-style:italic; src: local('BlexMonoLigNFM-BookItalic'), local('BlexMonoLig Nerd Font Mono Book Italic'); }
  /* bold(700) → Text(450) */
  @font-face { font-family:'Blex'; font-weight:bold;   font-style:normal; src: local('BlexMonoLigNFM-Text'),       local('BlexMonoLig Nerd Font Mono Text');        }
  @font-face { font-family:'Blex'; font-weight:bold;   font-style:italic; src: local('BlexMonoLigNFM-TextItalic'), local('BlexMonoLig Nerd Font Mono Text Italic'); }


  :root {
    --font-family-sans: /*[[font-family-sans]]*/;
    --font-family-github-mono: /*[[font-family-github-mono]]*/;
    --font-family-mono-accent: 'VictorMono Nerd Font Mono', 'Lekton Nerd Font Mono', 'LXGWWenKaiMono Nerd Font Mono', ui-monospace, SFMono-Regular, 'SF Mono', Menlo, Consolas, 'Liberation Mono', monospace;
    --font-family-handwritten: /*[[font-family-handwritten]]*/;
    --font-family-icon: /*[[font-family-icon]]*/;
    --font-family-override: /*[[font-family-sans]]*/;

    --font-size-big-sans: 20px;
    --font-size-normal-sans: 18px;
    --font-size-small-sans: 15px;

    --font-size-big-mono: 19px;
    --font-size-normal-mono: 17px;
    --font-size-small-mono: 15px;
    --font-size-xsmall-mono: 14px;

    --font-size-h1: 34px;
    --font-size-h2: 26px;
    --font-size-h3: 24px;
    --font-size-h4: 20px;
    --font-size-h5: 16px;

    --font-size-github-mono: var(--font-size-normal-mono);
  }

  html {
    --font-size-xsmall-mono: 13px;
    --font-size-h5: 16px;
  }

  body {
    font-family: var(--font-family-sans), var(--font-family-github-mono) !important;
  }

  /**
   * kbd, pre, code:                             html tag. e.g.: <kbd></kbd>, <pre></pre>
   * pre *, code *, div.line-numbers, div.code   html tag with class. e.g.: <div class="code"></div> <div class="line-numbers"></div>
   * .line, .line-number, .monospaced:           specific class name
   * #name, #number                              specific id name
   * :is(), :not(), :where(), :any()             Pseudo-classes https://developer.mozilla.org/en-US/docs/Web/CSS
   * :not(:is( ... ) )                           to exclude parent elements
  **/
  *:not(
    pre,
    code,
    textarea,
    button,
    select,
    option,
    cursor,
    kbd,
    icon,
    input,
    i
  ):not(::before):not(::after):not(canvas.graph-cursor-pointer):not(
    code *,
    textarea *,
    * pre *,
    div.ace_editor,
    .ace_editor *
  ):not(
    [class*="CodeMirror-"],
    [class*="DPvwYc"],
    [class*="Da"],
    [class*="ace_"],
    [class*="avatar-"],
    [class*="bowtie-"],
    [class*="cm-"],
    [class*="code"],
    [class*="drop"],
    [class*="fa-"],
    [class*="gr-"],
    [class*="hljs"],
    [class*="ico"],
    [class*="js-post"],
    [class*="language-"],
    [class*="line"],
    [class*="para"],
    [class*="pc"],
    [class*="pl-"],
    [class*="post-"],
    [class*="setting-"],
    [class*="sort-caret"],
    [class*="view-"],
    [class*="w3-"],
    [class*='wysiwyg-macro-*'],
    [role=presentation]
  ),
  .gr-app, .sidebar, div[class*="timeline"],
  div#book-search-input > input, span.algolia-autocomplete > input {
    font-family: var(--font-family-sans) !important;
  }


  /* ── global settings ────────────────────────────────────── */
  p:is([node="[object Object]"]) {
    font-family: var(--font-family-github-mono) !important;
  }

  p, h1, h2, h3, h4, h5, h6,
  code :where(h1, h2, h3, h4, h5, h6),
  pre :is(h1, h2, h3, h4, h5, h6),
  button#btnSubmit, div.k-widget.k-grid *,
  div.breadcrumbs *, ul.one-third *,
  ul.code_language_large *, .a-center,
  [class*="grepper_answer_button"] *,
  [class*="answer_title"] {
    font-family: var(--font-family-sans) !important;
  }
  h1.page-header :not([class*="hidden-"]),
  h1 span.pre,
  [class*="header"]:not(
    [class*="content"],
    [class*="navbar-"]
  ) > h1:not(
    [title="Class Descriptor"]
  ) :not(button):not(button+div):not(
    a[class*="Tab"],
    a[class*="tab"],
    i[class*="fa"],
    [class*="aui-dropdown2"] *,
    [class*="badge"],
    [class*="btn"],
    [class*="logo"],
    [class*="text-normal"] *,
    [class*="text-xs"]
  ),
  h1#gh-pages code,
  div[class*="headline"]:not(
    [class*="-view-model"],
    [class*="container__"]
  ) *:not(
    [class*="bot-status-badge"],
    [class*="btn"],
    [class*="byline__"],
    [class*="container__"],
    [class*="headline__"],
    [class*="timestamp"]
  ),
  div#click-to-connect > div > :not(h1):not(h2),
  .markdown-body h1, .markdown-section h1 {
    font-size: var(--font-size-h1) !important;
    font-weight: 500 !important;
  }

   h1 > code, h1 > a > code,
  *:not(blockquote) > h2:not(
      [class*="f4"],                                          /* github fork list */
      [class*="InlineReviewThread"]                           /* PR file change inline review header */
   ) >
    :is(
      a:not([class*="css-"]),
