    font-family: 'LektonLig Nerd Font Mono', var(--font-family-mono) !important;
    font-size: var(--font-size-big-mono) !important;
  }

  /* for chrome plugin: JSON Viewer Pro */
  .jv-code-editor { font-size: 20px !important;  }

