  kbd,
  option, option *,
  canvas, canvas *,
  pre code, pre code *,
  pre code ul li *,
  code:not(h1 code, h2 code, h3 code, h4 code, h5 code, h6 code, .desc code), code:not(h1 code, h2 code, h3 code, h4 code, h5 code, h6 code, .desc code) *,
  input :where(code, pre),
  select, select *,
  script, script *,
  textarea, textarea *,
  #view-message>pre, #view-message>pre *, div#view-message>pre, div#view-message>pre *,
  #side-panel>pre, #side-panel>pre *, div#side-panel>pre, div#side-panel>pre *,
  .code, .code *,
  div.code *, table.code, table.code *, table.pre, table.pre *,
  .jenkins-input,
