  #main-panel > pre.console-output span.timestamp,                      /* console output timestamp */
  #main-panel > pre.console-output span.timestamp b,
  #main-panel > pre.console-output span.timestamp * {
    font-family: 'IosevkaPlexMarslo Nerd Font Mono', 'LektonLig Nerd Font Mono', var(--font-family-mono-accent) !important;
    color: #696969 !important;
