  a.anchorjs-link::after {
    font-family: "anchorjs-icons" !important;
  }

  span.jenkins-icon-adjacent {
    font-family: var(--font-family-handwritten);
    font-size: 100% !important;
  }

  .log-header {
    font-family: var(--font-family-sans) !important;
    font-size: var(--font-size-big-sans) !important;
  }

  /* bluetooth */
  .result-item-label,
  .TruncatingLabel,
  [class*="RunDetailsHeader"] *,
  [class*="JTable"],
  .activity-actions-container,
  .Header-pageTabs,
  .development-footer {
    font-size: var(--font-size-normal-mono) !important;
  }

  select {
    outline: 0 !important;
  }

  /* comments */
  span.pipeline-new-node, span.cm-comment, .ace-tomorrow .ace_comment, span.ace_comment {
    font-style: italic !important;
  }
  .ace-tm .ace_comment, span.cm-comment {                     /* comments */
    color: darkgray !important;
  }

  /* ── pipeline graph view - pipeline-console ── */
  div.log-card--header, .log-card--header.step-detail-group, .log-card--header.step-header {
    font-family: var(--font-family-mono-accent) !important;
    font-size: var(--font-size-big-mono) !important;
    font-weight: 600 !important;
  }
  div.pgv-step-detail-header__actions span,                   /* higher-version pgv - timestamp */
  div.pgv-step-detail-header__content span,                   /* higher-version pgv - content */
  div.pgv-tree-item__description, div.pgv-tree-item__name,    /* higher-version pgv - sidebar */
  div.log-card--text {
    font-family: 'AtkynsonNext Nerd Font' !important;
  }
  div.pgv-step-detail-header__content span {
    font-size: var(--font-size-normal-sans) !important;
  }
  .css-9l3uo3 {
    font-family: var(--font-family-mono) !important;
    font-size: var(--font-size-small-mono) !important;
    font-style: italic !important;
  }
  .css-3wafqk {
    font-family: var(--font-size-big-mono-accent) !important;
    font-size: var(--font-size-big-mono) !important;
    white-space: pre-wrap !important;
  }

  /* ── inline badge (e.g. uppercase "MANDATORY FIELD") in parameter/form description ── */
  .jenkins-form-description span[style*="background"],
  .jenkins-form-description span[style*="text-transform"] {
    display: inline-block !important;
    line-height: 1 !important;
    text-box-trim: trim-both !important;
    text-box-edge: cap alphabetic !important;
    text-box: trim-both cap alphabetic !important;             /* shorthand fallback */
    /* font-family: "Gisha Nerd Font" !important; */
    /* trimming removes the line-box leading, so add the vertical breathing room back */
    padding-block: .4em !important;
  }

  /* ── BUILD_NAME width in build history ── */
  /* header row = build-name (wraps, takes remaining width) + badges (fixed, top-right) */
  .build-row-cell .block.wrap.build-name-controls {
    display: flex !important;
    align-items: flex-start;     /* keep badges on the first line, not centered over `desc` */
    gap: 6px;
  }
  .build-row-cell .block.wrap.build-name-controls > .pane.build-name.wrapped {
    float: none !important;      /* drop float; use a flex item instead of block/float layout */
    flex: 1 1 auto;              /* take the remaining width */
    min-width: 0;                /* allow long build names to wrap */
    width: auto !important;
    max-width: 100% !important;  /* DO NOT exceeding the parent element */
    height: auto !important;
    box-sizing: border-box;
  }
  /* <a> link: allow consecutive character newlines */
  .build-row-cell .pane.build-name.wrapped > a.display-name {
    display: block;
    max-width: 100%;
    min-width: 0;
    box-sizing: border-box;
    word-break: break-all;
    overflow-wrap: anywhere;
  }

  /* ── BADGE(s) pinned top-right; never overlapped by a wide `desc` table ── */
  .build-row-cell {
    position: relative;
  }
  .build-row-cell .build-name-controls > .pane.build-controls.wrapped {
    float: none !important;      /* drop float; flex item instead */
    flex: 0 0 auto;              /* natural width, never shrink away */
    margin-left: auto;           /* push to the right edge of the header row */
  }

  /* ── stage view ── */
  .changeset-box {
    display: flex;
    align-items: center;      /* centered vertically   */
    justify-content: center;  /* centered horizontally */
  }

} /* @-moz-document: jenkins */

