  .ordo2,
  .KskmCc,
  .AarNVd,
  .MXuJQd,
  .KmsAmb .tL9Q4c,
  .uNr6ee,
  .fEU59c,
  .v2OCrb,
  .WFnNle,
  .qSb8Pe,
  .NqnNQd,
  .lRu31,
  .lrSgmd {
    color: var(--fg-primary) !important;
  }

  button,
  .VlPnLc svg,           /** footer **/
  .TcXXXb {
    color: var(--blue) !important;
  }
  .EYBmYc,                /** history **/
  .kgJkHd {                /** saved **/
    color: var(--yellow) !important;
  }
  .ZihNHd.EmpJsc > span > .NMm5M {
    color: var(--hints) !important;
  }

  .eIKIse,               /** ╮ Noun, Verb, ... **/
  .jq25U {                 /** ╯                 **/
    color: var(--yellow) !important;
  }

  .U8K5nb {
    background: var(--blue) !important;
    color: var(--on-accent) !important;
    border: 1px solid var(--blue) !important;
  }

  /** More translations **/
  .ydsGXd {
    background-color: var(--bg-primary) !important;
    color: var(--blue) !important;
  }

  div.sbtc,
  .gsfi,
  .lst {
    font-family: var(--font-family-mono) !important;
  }

  .g,
  .std,
  a.k8XOCe *,
  a.fl,
  div.ZOyvub,
  div.m0uvVb *,
  div.P1usbc *,
  .wrBvFf > a,
  .HiHjCd > a,
  cite.iUh30,
  cite.iUh30 > span,
  span.go,
  table.CFNMfb * {
    font-family: var(--font-family-sans) !important;
  }

  .wrBvFf > a,
  .HiHjCd > a,
  cite.iUh30,
  cite.iUh30 > span,
  span.go {
    font-size: 14px !important;
  }

  .FvchS {
    position: relative;
  }

  /**
   * button of `Text`, `Images`, `Documents`, `Websites`
   * can hidden via `.hgbeOc { visibility: hidden; }`
  **/
  /* button-group: outlined, current mode ( `aria-current="page"` ) filled */
  .Rj2Mlf:not(:disabled) {
    background-color: transparent !important;
    border-color: var(--bg-hover) !important;
    color: var(--fg-primary) !important;
  }
  .Rj2Mlf:not(:disabled):hover {
    background-color: var(--comment) !important;
  }
  .Rj2Mlf[aria-current="page"]:not(:disabled),
  .gwGW9e {
    background-color: var(--cyan) !important;
    border-color: var(--cyan) !important;
    color: var(--on-accent) !important;
  }

  /** search languages activated **/
  .qSb8Pe.KKjvXb {
    background-color: var(--bg-primary) !important;
    color: var(--green) !important;
  }


  .a88hkc,               /** feedback-link **/
  .gHNJvf,               /** voice-input-button **/
  .nidPne,               /** keyboard-ui-button **/
  .vNTDhc {                /** rate this translate **/
    display: none;
  }

  ::-webkit-scrollbar {    /** scrollbar **/
    background-color: var(--bg-secondary) !important;
  }

  span .VfPpkd-YVzG2b::after {
    color: var(--green) !important;
  }

  /** images search **/
  .D7BEKc:focus-within .CQQi5b,
  .CQQi5b {
    background: var(--green) !important;
  }
  .FJCnk {                 /** hr **/
    border: 1px solid var(--cyan) !important;
  }
  .q7OsL,                /** board **/
  .eTNoGb {
    border: none !important;
  }
  .rlWbvd,
  .pu3MFc,
  .uqt39c,
  .LYeNu,
  .sp2Bqb {
    background: var(--comment) !important;
    color: var(--fg-primary) !important;
  }
  .zXU7Rb {
    border-top-left-radius: 0px;
    border-top-right-radius: 0px;
  }

  /** documents **/
  .uqt39c,
  .sp2Bqb,
  .k5v5Nb {
    font-family: var(--font-family-sans) !important;
  }

  /** website **/
  input#i48 {              /** cursor **/
    caret-color: var(--fg-primary) !important;
  }

  body#yDmH0d > c-wiz > div > div:nth-child(2) > c-wiz > div:nth-child(4) > c-wiz > div:nth-child(3) > div > span > button:not(:disabled) {
    background-color: var(--chip-bg) !important;
    color: var(--green) !important;
  }

  .VfPpkd-NLUYnc-V67aGc {  /** Website placeholder **/
    color: var(--fg-primary) !important;
  }

  /** input box boder **/
  .cfWmIb.VfPpkd-fmcmS-yrriRe-OWXEXe-XpnDCe:not(.VfPpkd-fmcmS-yrriRe-OWXEXe-OWB6Me) .VfPpkd-NSFCdd-Brv4Fb,
  .cfWmIb.VfPpkd-fmcmS-yrriRe-OWXEXe-XpnDCe:not(.VfPpkd-fmcmS-yrriRe-OWXEXe-OWB6Me) .VfPpkd-NSFCdd-Ra9xwd,
  .cfWmIb.VfPpkd-fmcmS-yrriRe-OWXEXe-XpnDCe:not(.VfPpkd-fmcmS-yrriRe-OWXEXe-OWB6Me) .VfPpkd-NSFCdd-MpmGFe,
  .cfWmIb.VfPpkd-fmcmS-yrriRe-OWXEXe-XpnDCe:not(.VfPpkd-fmcmS-yrriRe-OWXEXe-OWB6Me) .VfPpkd-NLUYnc-V67aGc {
    border-color: var(--gm-outlinedtextfield-outline-color--stateful,var(--fg-primary)) !important;
  }

  /** hover or select sentence **/
  .WtlSJf:hover,
  .Xcmxjb.FwR7Pc,
  .jCAhz.C1N51c,
  .jCAhz:hover {
    background-color: var(--bg-hover) !important;
  }
  .NWlwsb {
    background-color: var(--comment) !important;
    color: var(--fg-primary) !important;
    font-family: var(--font-family-mono) !important;
    border: 1px solid color-mix(in srgb, var(--fg-secondary) 80%, transparent);
    border-radius: 8px;
    box-shadow: 1px 2px 8px 4px var(--bg-secondary) !important;
  }
  .WtlSJf.KKjvXb {
    background-color: var(--bg-third) !important;
  }

  /** see dictionary **/
  .yP8PRe {
    color: var(--cyan) !important;
  }
  .AzGRq.VfPpkd-StrnGf-rymPhb-ibnC6b {
    border: 1px solid color-mix(in srgb, var(--fg-secondary) 80%, transparent);
    border-radius: 2px;
  }

  /** background color after click **/
  span.jCAhz.ChMk0b.C1N51c {
    background-color: var(--bg-hover) !important;
  }

  .s0ijVb {
    background-color: var(--bg-primary) !important;
  }
  .rm1UF,
  .QcsUad {
    border: 1px solid var(--bg-primary);
    border-radius: 6px;
    box-shadow: inset 0 0 3px 2px var(--comment) !important;
  }

  /** settings **/
  .VfPpkd-xl07Ob-XxIAqe {
    color: var(--fg-primary);
    background-color: var(--comment) !important;
    border: 1px solid var(--bg-primary) !important;
  }
  .pWIpbc,
  .Jp7KKb,
  .XOPM0 {
    color: var(--fg-primary);
  }

  /** expand all/collapse all **/
  .qt6jm {
    border-top: 2px solid;
    justify-content: flex-end;
    padding: 0 16px;
    background-color: var(--comment) !important;
    border-radius: 8px;
  }
  .hX7wnb {
    background-color: var(--bg-primary) !important;
    border-top-color: var(--bg-third) !important;
  }

  /** history / saved panel **/
  .vDGmEc,
  .kmXzdf,
  .uojYg {
    border-color: var(--bg-third) !important;
    outline-color: var(--bg-third) !important;
    background-color: var(--bg-primary) !important;
  }
  .NBY4Kb {                /** history footer **/
    background-color: var(--bg-primary) !important;
    border-color: var(--bg-third) !important;
  }
  .SdtK5b {                /** manage all activity **/
    color: var(--blue) !important;
  }
  .vDGmEc *:not(.j27i7),
  .uojYg *:not(.j27i7) {  /** item separators **/
    border-color: var(--bg-third) !important;
  }
  .VlPnLc .ySES5,
  .VlPnLc .mqNsCe:hover .ySES5 {  /** history / saved circle button **/
    border-color: var(--bg-third) !important;
  }

  /** google menu **/
  .gb_Ea:not(.gb_bc) .gb_1c>* {
    background-color: var(--bg-primary) !important;
  }
  .gb_Vc .gb_Qc, .vpl77 {
    background-color: var(--bg-primary);
    color: var(--fg-primary);
    font-family: var(--font-family-sans);
  }

sourceCode:
/* ==UserStyle==
@name           Google GruvBox Material
@namespace      github.com/marslo
@version        2.2.0
@description    gruvbox-material ( dark / light × hard / medium / soft ) theme for google search ( incl. ai mode ) and translate
@author         Marslo Jiao
@homepageURL    https://github.com/marslo/google-gruvbox
@preprocessor   uso
@var select     palette "Palette" {
  "Dark Hard*": "html:root { --gruv-palette: dark-hard; }",
  "Dark Medium": "html:root { --gruv-palette: dark-medium; --bg-primary: #282828; --bg-secondary: #1b1b1b; --bg-third: #45403d; --bg-hover: #5a524c; --comment: #32302f; }",
  "Dark Soft": "html:root { --gruv-palette: dark-soft; --bg-primary: #32302f; --bg-secondary: #252423; --bg-third: #504945; --bg-hover: #665c54; --comment: #3c3836; }",
  "Light Hard": "html:root { --gruv-palette: light-hard; color-scheme: light; --bg-primary: #f9f5d7; --bg-secondary: #f3eac7; --bg-third: #f2e5bc; --bg-hover: #ebdbb2; --comment: #f5edca; --fg-primary: #654735; --fg-secondary: #7c6f64; --red: #c14a4a; --green: #6c782e; --yellow: #b47109; --blue: #45707a; --magenta: #945e80; --cyan: #4c7a5d; --orange: #c35e0a; --chip-bg: #ebdbb2; --icon-filter: none; --on-chip: var(--fg-primary); }",
  "Light Medium": "html:root { --gruv-palette: light-medium; color-scheme: light; --bg-primary: #fbf1c7; --bg-secondary: #f2e5bc; --bg-third: #eee0b7; --bg-hover: #ddccab; --comment: #f4e8be; --fg-primary: #654735; --fg-secondary: #7c6f64; --red: #c14a4a; --green: #6c782e; --yellow: #b47109; --blue: #45707a; --magenta: #945e80; --cyan: #4c7a5d; --orange: #c35e0a; --chip-bg: #ddccab; --icon-filter: none; --on-chip: var(--fg-primary); }",
  "Light Soft": "html:root { --gruv-palette: light-soft; color-scheme: light; --bg-primary: #f2e5bc; --bg-secondary: #ebdbb2; --bg-third: #e6d5ae; --bg-hover: #d5c4a1; --comment: #eddeb5; --fg-primary: #654735; --fg-secondary: #7c6f64; --red: #c14a4a; --green: #6c782e; --yellow: #b47109; --blue: #45707a; --magenta: #945e80; --cyan: #4c7a5d; --orange: #c35e0a; --chip-bg: #d5c4a1; --icon-filter: none; --on-chip: var(--fg-primary); }"
}
==/UserStyle== */

@-moz-document domain("www.google.com") {
  html {
    color-scheme: dark;
    --bg-primary: #1d2021;
    --bg-secondary: #141617;
    --bg-third: #3c3836;
    --bg-hover: #504945;
    --comment: #282828;
    --fg-primary: #d4be98;
    --fg-secondary: #a89984;
    --red: #ea6962;
    --green: #a9b665;
    --yellow: #d8a657;
    --blue: #7daea3;
    --magenta: #d3869b;
    --cyan: #89b482;
    --orange: #e78a4e;
    --hints: color-mix(in srgb, var(--yellow) 80%, var(--fg-secondary));
    --on-accent: var(--bg-primary);
    --chip-bg: #d4be98;
    --on-chip: var(--bg-primary);
    --icon-filter: invert(1);
    --font-family-sans: "Titillium Nerd Font Upright", "Titillium Nerd Font", "Recursive Sans Casual Static Nerd Font", "MicrosoftYaHei Nerd Font", "Recursive", "Ubuntu", "Candara", "Gisha", "Titillium", "Google Sans", "Roboto", "Helvetica Neue", "arial", sans-serif;
    --font-family-mono: "OperatorMonoSSmLig Nerd Font Mono", "OperatorMonoLig Nerd Font Mono", "OperatorMono Nerd Font Mono", "JetBrainsMono Nerd Font Mono", "RecMonoCasual Nerd Font Mono", "Monaco Nerd Font Mono", Menlo, "Andale Mono", "Ubuntu Mono", "Monofur Nerd Font Mono", Consolas, "Yozai Nerd Font";
  }
  /* gruvbox-material, foreground `material`: `dark` + `hard` above, other palettes via `@var select palette` ( https://github.com/sainnhe/gruvbox-material/blob/master/autoload/gruvbox_material.vim ) */
  /*[[palette]]*/

  body,
  #hdtbSum,
  #appbar,
  #gb,
  .c93Gbe,
  .s,
  .s .st em,
  .st.s.std em,
  .eJ7tvc,
  .s7d4ef,
  .jloFI,
  .EIJn2,
  .OZ9ddf .Fzsovc,
  #fbar,
  #pTwnEc,
  .sfbg {
    background: var(--bg-primary) !important;
    color: var(--fg-primary) !important;
  }

  code,
  textarea {
    font-family: var(--font-family-mono) !important;
  }

  /** ai mode input: textarea + mirrored caret ( `data-before` / `data-after` ) **/
  .Txyg0d,
  .Txyg0d .ITIRGe,
  .Txyg0d .CEpIFc,
  .Txyg0d .CEpIFc::before,
  .Txyg0d .CEpIFc::after {
    font-family: var(--font-family-mono) !important;
  }

  /** ai mode: remap google color tokens ( redeclared per component, hence `*` + `!important` ) **/
  * {
    --bbQxAb: var(--fg-primary) !important;
    --YLNNHc: var(--fg-primary) !important;
    --jINu6c: var(--fg-primary) !important;
    --TMYS9: var(--fg-primary) !important;
    --VuZXBd: var(--fg-primary) !important;
    --ZXiaGf: var(--bg-primary) !important;
    --IXoxUe: var(--fg-secondary) !important;
    --uLz37c: var(--fg-secondary) !important;
    --amnPwe: var(--fg-secondary) !important;
    --JKqx2: var(--blue) !important;
    --rrJJUc: var(--blue) !important;
    --TyVYld: var(--blue) !important;
    --jwFC2e: color-mix(in srgb, var(--blue) 35%, var(--bg-primary)) !important;
    --xhUGwc: var(--bg-primary) !important;
    --CwQ7J: var(--bg-primary) !important;
    --cIehld: var(--bg-primary) !important;
    --MV2sG: var(--comment) !important;
    --bcxd3b: var(--fg-primary) !important;
    --XKMDxc: var(--comment) !important;
    --DEeStf: var(--comment) !important;
    --vZe0jb: var(--comment) !important;
    --nwXobb: var(--comment) !important;
    --QWaaaf: var(--comment) !important;
    --ZEpPmd: var(--comment) !important;
    --aYn2S: var(--bg-third) !important;
    --TSWZIb: var(--bg-third) !important;
    --gS5jXb: var(--bg-third) !important;
    --mXZkqc: var(--bg-third) !important;
    --Lm570b: var(--bg-hover) !important;
    --BRLwE: var(--bg-hover) !important;
    --Nsm0ce: var(--blue) !important;
    --EpFNW: var(--on-accent) !important;
  }

  /** ai mode: hardcoded sidebar / input chip backgrounds **/
  .qEn1od,
  .ho072b {
    background-color: var(--bg-secondary) !important;
  }
  /* sidebar thread list: `.u987h` item, `.cp7uzb` current */
  .u987h:hover {
    background-color: color-mix(in srgb, var(--bg-hover) 60%, var(--bg-secondary)) !important;
  }
  .u987h.cp7uzb,
  .u987h.cp7uzb:hover {
    background-color: var(--bg-hover) !important;
  }
  /* sidebar thread `...` menu ( `.XGxljc` ): share / add to notebook ( `.QJP0n` submenu open ) / delete */
  .zJrqFf .eGAasd:hover,
  .zJrqFf .eGAasd:focus-visible,
  .FzQJwc:hover,
  .FzQJwc:focus-visible,
  .FzQJwc.QJP0n,
  .w7Y0zd:hover,
  .w7Y0zd:focus-visible {
    background-color: var(--bg-hover) !important;
  }
  .hhGtFb::after,
  .sisB6e::after {
    background-color: var(--bg-hover);
  }

  /** ai mode: widen top nav, response column and input plate to 85vw **/
  .DZ13He .P3mIxe {
    grid-column: 1 / -1 !important;
    justify-self: center;
    width: 85vw !important;
    max-width: none !important;
  }
  .WzWwpc .Rty6Hf {
    grid-column: 1 / -1 !important;
    justify-self: center;
    width: 85vw !important;
    --CYi3c--fRcLaf: 100%;
  }
  .Rty6Hf .mZJni,
  .Rty6Hf .TWKprf,
  .Rty6Hf .uU6vme {
    max-width: none !important;
  }
  .Rty6Hf .ilZyRc {
    max-width: calc(100% - var(--rhs-width, 372px) - var(--rhs-margin, 76px)) !important;
  }
  .y4VEUd .t0ITR:not(.AkYNS) {
    grid-column: 1 / -1 !important;
    justify-self: center;
    width: calc(85vw + 40px) !important;
    max-width: none !important;
  }


  a:link,
  .w,
  #prs a:visited,
  #prs a:active,
  .q:active,
  .q:visited,
  .kl:active,
  .tbotu,
  a.fl:link,
  .fl a,
  .flt,
  a.flt,
  .gl a:link,
  a.mblink,
  .mblink b,
  .i3LlFf,
  .kno-ecr-pt,
  .w8qArf .fl {
    color: var(--blue) !important;
  }


  .mblink:visited,
  a:visited {
    color: var(--magenta) !important;
  }


  .cv2VAd,
  .kp-blk,
  #fbar,
  .WwiUwd {
    background: var(--bg-secondary);
    border-color: var(--comment);
  }

  .gLFyf,
  .i29hTd .qLLird,
  .sbct:first-child .suggestions-inner-container,
  .RNNXgb {
    color: var(--fg-primary);
  }


  .aajZCb,
  .sbl1,
  .RNNXgb,
  .sbhl {
    background: var(--bg-primary);
    border-radius: 24px !important;
    border: 1px solid var(--cyan);
    color: var(--fg-primary);
    font-family: var(--font-family-mono) !important;
  }

  .RNNXgb:hover {
    background: var(--bg-third);
    border: 1px solid var(--cyan);
  }

  textarea.gLFyf,
  .YacQv,
  #result-stats {
    font-family: var(--font-family-mono) !important;
  }

  .SDkEP {
    color: var(--fg-primary) !important;
  }

  /*
  .SDkEP
  .Tg7LZd
    background: var(--bg-primary);
  */

  .ExCKkf > svg {
    color: var(--red);
  }

  .QCzoEc > svg {
    color: var(--cyan);
  }

  .zgAlFc > span > svg {
    color: var(--orange);
  }


  .k8XOCe,
  .R0xfCb,
  .VCOFK,
  .s8bAkb {
    background: var(--bg-primary);
  }

  .s75CSd,
  .OhScic,
  .AB4Wff {
    color: var(--cyan);
  }

  .sbct:hover {
    border: none !important;
    background: var(--comment);
    cursor: pointer;
  }

  .JCHpcb {
    color: var(--red) !important;
  }

  .wM6W7d,
  .WggQGd {
    /** color: var(--magenta) !important; **/
    color: var(--fg-secondary) !important;
    font-family: var(--font-family-sans) !important;
  }

  .minidiv .sfbg {
    background: var(--bg-secondary);
  }
  /* sticky header after scroll ( `.VHFyob`, background from unmapped `--cIehld` ) */
  .VHFyob .CvDJxb {
    background: var(--bg-secondary) !important;
  }
  /* "people also search for" chips ( `.b2Rnsc`, hardcoded `#f1f3f4` / text `#e8e8e8` ) */
  .b2Rnsc {
    background: var(--comment) !important;
  }
  .b2Rnsc:hover {
    background: var(--bg-third) !important;
  }
  .b2Rnsc .dg6jd {
    color: var(--fg-primary) !important;
  }
  /* "view all" / "show more" pill ( `.ZFiwCf` ), hardcoded variants `#2c2e35` / `#373839` */
  .MagqMc .ZFiwCf,
  .sOmPcf .ZFiwCf {
    background-color: var(--comment) !important;
    border-color: var(--bg-third) !important;
  }
  .ZFiwCf:hover::after {
    background-color: color-mix(in srgb, var(--fg-primary) 10%, transparent) !important;
  }

  .g,
  .ssJ7i,
  .iAIpCb,
  .JNkvid .HnYYW,
  .e9EfHf,
  .fm06If .ILfuVd,
  .c2xzTb .ILfuVd,
  .Jb0Zif .c2xzTb .ILfuVd,
  .w5mTAe .ILfuVd,
  .W0urI .ILfuVd,
  .clOx1e,
  .jloFI,
  .HJSKzf, .wHYlTd, .JgzqYd,                           /* translator in Google */
  .YmvwI,                                              /* navigator: All | Images | Shopping | ... */
  .FMKtTb, .Lu57id,
  .IFnjPb, .CSkcDe, .related-question-pair div.iDjcJe, /* People also ask */
  .X4xFHd, .fXNJzc {
    font-family: var(--font-family-sans) !important;
  }
  .wHYlTd,
  .aztjNb {
    line-height: 22px !important;
  }

  #hdtb {
    border: none;
  }


  .GHDvEf,
  .GHDvEf:hover,
  .GHDvEf.selected,
  .GHDvEf.selected:hover {
    background: var(--comment);
